<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/app/Config/bootstrap.php';
use App\Core\Database;use App\Middleware\AdminGuard;use App\Middleware\Csrf;use App\Services\AuthService;use App\Services\AdminStorefrontService;
use App\Services\ImageUploadService;
AdminGuard::require();$admin=(new AuthService())->admin()??[];$adminName=(string)($admin['name']??'مدیر');$adminEmail=(string)($admin['email']??'');$pageTitle='مدیریت بنرها';$activeSection='banners';$service=new AdminStorefrontService();$error='';$success='';$editId=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT)?:null;$form=['title'=>'','subtitle'=>'','image_path'=>'','link_url'=>'','sort_order'=>0,'is_active'=>1];$banners=[];
if(!Database::configured())$error='اتصال دیتابیس تنظیم نشده است.';else try{
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!Csrf::verify($_POST['_csrf']??null))throw new InvalidArgumentException('درخواست معتبر نیست؛ صفحه را تازه‌سازی کنید.');
  if(!Csrf::verifyForm('banners',is_string($_POST['form_token']??null)?$_POST['form_token']:null))throw new InvalidArgumentException('این فرم قبلاً ارسال شده یا منقضی شده است؛ صفحه را تازه‌سازی کنید.');
  $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT)?:null;
  if(($_POST['action']??'save')==='delete'){$service->deleteBanner((int)$id);Csrf::consumeForm('banners');$_SESSION['admin_flash']='بنر حذف شد.';header('Location: ' . url('admin/banners.php'), true, 303);exit;}
  $uploadedImage=(new ImageUploadService())->store($_FILES['image_file']??null);if($uploadedImage!==null)$_POST['image_path']=$uploadedImage;$service->saveBanner($_POST,$id);Csrf::consumeForm('banners');$_SESSION['admin_flash']=$id?'بنر ویرایش شد.':'بنر ثبت شد.';header('Location: ' . url('admin/banners.php'), true, 303);exit;
 }
 $success=(string)($_SESSION['admin_flash']??'');unset($_SESSION['admin_flash']);
 if($editId){$found=$service->banner($editId);if(!$found)throw new InvalidArgumentException('بنر پیدا نشد.');$form=array_merge($form,$found);}
 $banners=$service->banners();
}catch(InvalidArgumentException $e){$error=$e->getMessage();$form=array_merge($form,$_POST);$banners=$service->banners();}catch(Throwable $e){$error='عملیات انجام نشد؛ ساختار دیتابیس را بررسی کنید.';}
$bannerFormToken=Csrf::formToken('banners');
require __DIR__.'/partials/header.php';?>
<section class="admin-panel"><div class="panel-heading"><div><span>اسلایدر و کمپین‌ها</span><h2><?=$editId?'ویرایش بنر':'افزودن بنر جدید'?></h2></div></div><?php if($error):?><div class="crud-alert error"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="crud-alert success"><?=e($success)?></div><?php endif;?>
<form class="crud-form" method="post" enctype="multipart/form-data" action="<?= e(url('admin/banners.php')) ?>"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="form_token" value="<?=e($bannerFormToken)?>"><input type="hidden" name="action" value="save"><?php if($editId):?><input type="hidden" name="id" value="<?=(int)$editId?>"><?php endif;?>
<label>عنوان بنر *<input name="title" maxlength="180" required value="<?=e($form['title']??'')?>"></label><label>زیرعنوان<textarea name="subtitle" maxlength="500" rows="2"><?=e($form['subtitle']??'')?></textarea></label>
<label class="wide">تصویر بنر<input type="file" name="image_file" accept=".jpg,.jpeg,.png,.webp,.avif,image/jpeg,image/png,image/webp,image/avif"><small>JPG، JPEG، PNG، WEBP یا AVIF؛ حداکثر ۵ مگابایت. عدم انتخاب فایل، تصویر فعلی را حفظ می‌کند.</small><input type="hidden" name="image_path" value="<?=e($form['image_path']??'')?>"></label><label class="wide">لینک مقصد<input name="link_url" dir="ltr" type="url" placeholder="https://example.com" value="<?=e($form['link_url']??'')?>"></label><label>ترتیب نمایش<input type="number" name="sort_order" value="<?=e($form['sort_order']??0)?>"></label><div class="crud-checks"><label><input type="checkbox" name="is_active" value="1" <?=!empty($form['is_active'])?'checked':''?>> نمایش در سایت</label></div><div class="crud-actions"><button class="crud-button primary" type="submit"><?=$editId?'ذخیره تغییرات':'ثبت بنر'?></button><?php if($editId):?><a class="crud-button secondary" href="<?= e(url('admin/banners.php')) ?>">انصراف</a><?php endif;?></div></form></section>
<section class="admin-panel"><div class="panel-heading"><div><span>مدیریت اسلایدها</span><h2>بنرها (<?=count($banners)?>)</h2></div></div><div class="crud-table-wrap"><table class="crud-table"><thead><tr><th>عنوان</th><th>تصویر</th><th>وضعیت</th><th>ترتیب</th><th>عملیات</th></tr></thead><tbody><?php foreach($banners as $b):?><tr><td><b><?=e($b['title'])?></b><small><?=e($b['subtitle']??'')?></small></td><td><?=e($b['image_path']??'—')?></td><td><span class="crud-status <?=$b['is_active']?'on':'off'?>"><?=$b['is_active']?'فعال':'غیرفعال'?></span></td><td><?=(int)$b['sort_order']?></td><td class="crud-row-actions"><a href="<?= e(url('admin/banners.php') . '?edit=' . (int) $b['id']) ?>">ویرایش</a><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="form_token" value="<?=e($bannerFormToken)?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$b['id']?>"><button type="submit">حذف</button></form></td></tr><?php endforeach;?><?php if(!$banners):?><tr><td colspan="5" class="crud-empty">هنوز بنری ثبت نشده است.</td></tr><?php endif;?></tbody></table></div></section><?php require __DIR__.'/partials/footer.php';
